{
  "IP": "neorv32_debug_auth",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Authentication-valid state",
      "Unit": "neorv32_debug_auth",
      "Information": "The authentication-valid state is the one-bit authorization value loaded from wdata_i(0) or cleared when disabled; debug authentication depends on retaining this state, and valid_o reports it.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The authentication-valid state may be sensitive authentication status, and line 66 exposes authenticated_q directly on valid_o. An attacker able to alter the write path can forge or clear the state because wdata_i(0) loads it at line 57 and enable_i or we_i controls that update at lines 54-57. Holding enable_i low repeatedly clears the state at lines 54-55, so valid_o at line 66 cannot remain asserted and authenticated debug operation can be withheld.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could observe valid_o and manipulate we_i, wdata_i, or enable_i to learn, forge, or clear the authentication state.",
      "Enters Through": [
        "wdata_i"
      ],
      "Leaves Through": [
        "valid_o"
      ],
      "Entry Lines": [
        57
      ],
      "Held Lines": [
        52,
        55,
        57
      ],
      "Exit Lines": [
        66
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Authentication enable control",
      "Unit": "neorv32_debug_auth",
      "Information": "The authentication-enable decision is enable_i's control of whether the authentication state is cleared or may be written; the authenticator's ability to retain an authenticated condition depends on it.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Changing enable_i changes authenticated_q through the clear assignment at lines 54-55, allowing unauthorized modification of authentication behavior. Holding enable_i low clears authenticated_q at lines 54-55 and withholds the asserted valid_o state at line 66, disabling authenticated operation.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could force enable_i low to invalidate authentication or toggle it during a write to alter the resulting authorization state.",
      "Enters Through": [
        "enable_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        54
      ],
      "Held Lines": [
        54
      ],
      "Exit Lines": []
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Authentication write command",
      "Unit": "neorv32_debug_auth",
      "Information": "The write-access command represented by we_i determines whether wdata_i can update the authentication state.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Changing we_i at line 56 controls whether wdata_i(0) is committed to authenticated_q at line 57, permitting unauthorized authentication changes. Suppressing we_i prevents the required authentication write from reaching authenticated_q, so valid_o cannot be established or updated.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could assert we_i with a selected wdata_i value to forge authentication or suppress we_i to prevent authentication.",
      "Enters Through": [
        "we_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        56
      ],
      "Held Lines": [
        56
      ],
      "Exit Lines": []
    }
  ],
